<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --checkpoint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> models/ModelLekai/epoch_4_1104_1204/model.safetensors</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
